def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import numpy as np
    h = max(0, int(horizon))
    if h == 0:
        return []
    try:
        x = np.asarray(list(history), dtype=float).reshape(-1)
    except Exception:
        return [0.0] * h
    if x.size == 0:
        return [0.0] * h
    finite = np.isfinite(x)
    if not finite.any():
        return [0.0] * h
    if not finite.all():
        good = np.flatnonzero(finite)
        x = np.interp(np.arange(x.size), good, x[good])
    cap = np.finfo(float).max / 1000000.0
    x = np.clip(x, -cap, cap)
    n = x.size
    f = str(frequency).lower()
    if 'hour' in f:
        p = 24
    elif 'quarter' in f:
        p = 4
    elif 'month' in f:
        p = 12
    elif 'week' in f:
        p = 52
    elif 'day' in f:
        p = 7
    else:
        p = max(2, min(24, n // 2))
    eps = np.finfo(float).eps * max(1.0, float(np.max(np.abs(x))))
    supported = False
    if n >= 2 * p:
        seasonal_error = float(np.median(np.abs(x[p:] - x[:-p])))
        persistence_error = float(np.median(np.abs(np.diff(x)))) if n > 1 else 0.0
        supported = seasonal_error <= 0.85 * persistence_error + eps
    out = []
    if supported:
        start = max(0, n - 4 * p)
        for j in range(h):
            phase = (n + j) % p
            vals = [float(x[i]) for i in range(start, n) if i % p == phase]
            out.append(float(np.median(vals)) if vals else float(np.median(x[-p:])))
    else:
        width = min(n, max(3, p // 2))
        level = float(np.median(x[-width:]))
        out = [level] * h
    return [float(np.clip(v, -cap, cap)) if np.isfinite(v) else 0.0 for v in out]
